import{_ as r,o as a,c as e,a2 as o}from"./chunks/framework.BXzK3EA4.js";const h=JSON.parse('{"title":"什么是双ISP DIA","description":"","frontmatter":{"title":"什么是双ISP DIA"},"headers":[],"relativePath":"ip-network/dual-isp-dia/what-is.md","filePath":"ip-network/dual-isp-dia/what-is.md","lastUpdated":1793693502000}'),d={name:"ip-network/dual-isp-dia/what-is.md"};function I(i,t,P,n,p,s){return a(),e("div",null,[...t[0]||(t[0]=[o('<p>双ISP DIA（英文：Dual ISP DIA）是 RakSmart 提供的一种带宽线路类型，采用具有 ISP（Internet Service Provider，互联网服务提供商）分类属性的 IP 资源。</p><p><strong>双 ISP IP</strong> 是市场上对一种 IP 网络身份分类特征的描述，通常指一个 IP 地址关联的公司类型（Company Type）与所属自治系统类型（ASN Type）均被识别为 ISP。</p><p>其中：</p><ul><li><p><strong>Company Type = ISP：</strong> IP 关联的公司被识别为互联网服务提供商。</p></li><li><p><strong>ASN Type = ISP：</strong> IP 关联的自治系统所属组织被识别为互联网服务提供商。</p></li></ul><p>需要注意，双 ISP 是一种市场上的 IP 属性描述，并非统一的行业认证标准。不同 IP 数据库可能采用不同的识别规则，因此具体分类结果可能存在差异。</p><hr><h3 id="名称含义" tabindex="-1">名称含义 <a class="header-anchor" href="#名称含义" aria-label="Permalink to &quot;名称含义&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>含义</th></tr></thead><tbody><tr><td>ISP</td><td>Internet Service Provider，互联网服务提供商（运营商）。</td></tr><tr><td>双 ISP</td><td>IP 的 <strong>ASN 类型</strong>（自治系统类型）与 <strong>公司类型</strong> 两项均为 ISP。</td></tr></tbody></table><hr><h3 id="ip-属性为什么重要" tabindex="-1">IP 属性为什么重要 <a class="header-anchor" href="#ip-属性为什么重要" aria-label="Permalink to &quot;IP 属性为什么重要&quot;">​</a></h3><p>每个公网 IP 都会登记在公开的 IP 数据库中，包含所属网络、所属公司、网络类型等信息，就像 IP 的&quot;身份信息&quot;。海外平台判断访问来源时，会参考这些信息：</p><ul><li><strong>普通机房 IP</strong>：通常登记为数据中心（Hosting / IDC），部分平台会对这类 IP 加强验证或限制访问。</li><li><strong>双 ISP IP</strong>：登记信息为运营商（ISP），网络属性更接近普通用户上网使用的 IP，有助于减少因 IP 身份引起的频繁验证和访问受限。</li></ul><hr><h3 id="ip-身份示例" tabindex="-1">IP 身份示例 <a class="header-anchor" href="#ip-身份示例" aria-label="Permalink to &quot;IP 身份示例&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>示例</th></tr></thead><tbody><tr><td>IP</td><td>xxx.xxx.xxx.xxx</td></tr><tr><td>ASN</td><td>AS 编号 · 运营商名称</td></tr><tr><td>ASN Type（自治系统类型）</td><td>ISP</td></tr><tr><td>Company Type（公司类型）</td><td>ISP</td></tr></tbody></table><p>两项均为 ISP，即为&quot;双 ISP&quot;。</p><blockquote><p><strong>说明</strong></p><p>双 ISP IP 在市场上也常被称为&quot;家庭属性 IP&quot;或&quot;住宅属性 IP&quot;。不同数据库及平台对 IP 类型的识别标准可能存在差异，具体识别结果以实际查询为准。</p></blockquote>',17)])])}const S=r(d,[["render",I]]);export{h as __pageData,S as default};
